import {researchCSV} from './research-metrics.js';
import {summarizeRaterA,summarizeProgram} from './descriptive.js';
import {csv} from './engine.js';
const $=id=>document.getElementById(id);
export const GENDERS={female:'여성',male:'남성',other:'기타',unknown:'미입력'};
export const CORRECTIONS={none:'교정 안 함',glasses:'안경',contacts:'콘택트렌즈',other:'기타',unknown:'미입력'};
export const MODES={camera:'실제 웹캠',reference:'영상 관찰 A',demo:'데모 · 합성자료'};
const fmt=(v,d=1)=>v===null||v===undefined?'—':Number(v).toFixed(d);
const date=v=>v&&Number.isFinite(Date.parse(v))?new Date(v).toLocaleString('ko-KR'):'날짜 미등록';
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
const button=(text,fn,cls)=>{const b=el('button',text,cls);b.type='button';b.onclick=fn;return b;};
const today=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');};
export function mountRegistry({repo,getHistory,isBusy,prepare,openReview,notice,download,onRestored}){
 let active=null,editing=null;
 try{active=localStorage.getItem('gaze-active-participant');}catch{}
 function profiles(){return repo.listProfiles();}
 function allSubjects(){const all=new Map(profiles().map(p=>[p.id,p]));for(const s of getHistory())if(!all.has(s.meta.participant))all.set(s.meta.participant,{id:s.meta.participant,name:'기본정보 미등록',legacy:true});return [...all.values()];}
 function selectedProfile(){return profiles().find(p=>p.id===active)??null;}
 function select(id){if(isBusy()){notice('측정 종료 후 대상자를 바꿀 수 있습니다.',true);return;}active=id;try{localStorage.setItem('gaze-active-participant',id);}catch{}render();}
 function nextId(){const used=new Set(allSubjects().map(p=>p.id));let n=1;while([...used].some(id=>id==='P'+String(n).padStart(4,'0')||id.startsWith('P'+String(n).padStart(4,'0')+'-')))n++;return 'P'+String(n).padStart(4,'0')+'-'+crypto.randomUUID().slice(0,8);}
 function edit(profile=null){if(isBusy())return notice('측정 종료 후 기본정보를 수정하세요.',true);editing=profile?.id??null;const p=profile??{id:nextId()};$('profileForm').reset();for(const [field,id]of Object.entries({name:'profileName',id:'profileId',gender:'profileGender',age:'profileAge',ageAsOfDate:'profileAgeDate',correction:'profileCorrection',visionRight:'profileVisionRight',visionLeft:'profileVisionLeft',visionBasis:'profileVisionBasis',notes:'profileNotes'}))$(id).value=p[field]??(['gender','correction','visionBasis'].includes(field)?'unknown':'');if(!$('profileAgeDate').value)$('profileAgeDate').value=today();$('profileFeedback').textContent='';$('profileTitle').textContent=profile?'기본정보 수정':'대상자 등록';$('profileDialog').showModal();$('profileName').focus();}
 function act(mode){const p=selectedProfile();if(!p){notice('이 대상자의 이름과 기본정보를 먼저 등록하세요.');edit({id:active});return;}prepare(p,mode);}
 function sum(rows,source){let total=0,valid=0,inside=0,outside=0,missing=0,unclear=0,failed=0;for(const s of rows){const k=source==='a'?summarizeRaterA(s):summarizeProgram(s),f=k.fields.find(f=>f.field==='screen');total+=f.total;valid+=f.valid;inside+=f.categories.find(c=>c.category==='INSIDE').seconds;outside+=f.categories.find(c=>c.category==='OUTSIDE').seconds;missing+=f.missing;unclear+=f.unclear;failed+=f.failed??0;}return {total,valid,inside,outside,missing,unclear,failed};}
 function render(){try{
  const subjects=allSubjects(),query=$('subjectSearch').value.trim().toLowerCase();if(!subjects.some(p=>p.id===active))active=subjects[0]?.id??null;
  $('subjectCount').textContent=subjects.length+'명 · 저장된 기록 '+getHistory().length+'개';$('subjectList').replaceChildren();
  const found=subjects.filter(p=>(p.id+' '+p.name).toLowerCase().includes(query));for(const p of found){const count=getHistory().filter(s=>s.meta.participant===p.id).length,b=button('',()=>select(p.id),'subject-item'+(p.id===active?' selected':''));b.setAttribute('aria-pressed',String(p.id===active));b.append(el('strong',p.name),el('span',p.id+' · 기록 '+count+'회'+(p.legacy?' · 정보 등록 필요':'')));$('subjectList').append(b);}if(!found.length)$('subjectList').append(el('p','검색된 대상자가 없습니다.'));
  const detail=$('subjectDetail');detail.replaceChildren();const p=subjects.find(p=>p.id===active);if(!p){const empty=el('div',undefined,'card empty');empty.append(el('h2','첫 대상자를 등록하세요'),el('p','이름 또는 가명으로 시작하고, 성별·연령·시력 정보를 함께 보관합니다.'),button('대상자 등록',()=>edit(),'primary'));detail.append(empty);return;}
  const records=getHistory().filter(s=>s.meta.participant===active).sort((a,b)=>(b.startedAt??'').localeCompare(a.startedAt??''));
  const hero=el('div',undefined,'card subject-hero'),top=el('div',undefined,'subject-heading');top.append(el('div',p.id,'eyebrow'),button(p.legacy?'기본정보 등록':'기본정보 수정',()=>edit(p.legacy?{id:p.id}:p)));hero.append(top,el('h2',p.name));
  const info=el('div',undefined,'profile-facts');for(const [k,v]of [['성별',GENDERS[p.gender]??'미입력'],['만 나이',p.age===null||p.age===undefined?'미입력':p.age+'세'],['평소 시력교정',CORRECTIONS[p.correction]??'미입력'],['시력 · 오른눈 / 왼눈',fmt(p.visionRight,2)+' / '+fmt(p.visionLeft,2)],['시력 기준',({corrected:'교정시력',uncorrected:'나안시력'})[p.visionBasis]??'미입력'],['정보 기준일',p.ageAsOfDate||'미입력']]){const box=el('div');box.append(el('small',k),el('strong',v));info.append(box);}hero.append(info);if(p.notes)hero.append(el('p',p.notes));
  const actions=el('div',undefined,'actions subject-actions');actions.append(button(records.length?'새 측정 시작':'첫 측정 시작',()=>act('camera'),'primary'),button('영상 관찰 기록 추가',()=>act('reference')),button('데모로 연습',()=>act('demo')));hero.append(actions);detail.append(hero);
  const stats=el('div',undefined,'subject-stats');for(const [n,v,h]of [['실제 기록',records.filter(s=>s.meta.mode!=='demo').length+'회','웹캠 + 영상 관찰'],['데모 기록',records.filter(s=>s.meta.mode==='demo').length+'회','실제 자료와 별도'],['최근 기록',records[0]?new Date(records[0].startedAt).toLocaleDateString('ko-KR'):'아직 없음','같은 대상자 ID로 계속 누적']]){const b=el('div',undefined,'card');b.append(el('small',n),el('strong',v),el('p',h));stats.append(b);}detail.append(stats);
  if(records.length){const summary=el('div',undefined,'card table-card');summary.append(el('h2','이 대상자의 누적 관찰정보'),el('p','모드·자료 용도·자료원을 나눠 합산합니다. A의 판단 불가·미입력과 프로그램 측정 실패를 구분합니다.'));const table=el('table'),thead=el('thead'),hr=el('tr');['자료 그룹','자료원','전체 / 유효 구간','화면 안 / 밖 (초)','미입력 / 판단 불가 / 실패'].forEach(t=>hr.append(el('th',t)));thead.append(hr);table.append(thead);const body=el('tbody'),groups=new Map();for(const s of records){const k=s.meta.mode+'|'+s.meta.role;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(s);}for(const rows of groups.values())for(const source of ['a','program']){if(source==='program'&&rows.every(s=>s.referenceOnly))continue;const s=sum(rows,source),row=el('tr');[MODES[rows[0].meta.mode]+' · '+(rows[0].meta.role==='validation'?'재검증':'개발'),source==='a'?'평가자 A':'프로그램 관측',s.total+' / '+s.valid,fmt(s.inside)+' / '+fmt(s.outside),s.missing+' / '+s.unclear+' / '+s.failed].forEach(v=>row.append(el('td',v)));body.append(row);}table.append(body);const sc=el('div',undefined,'table-scroll');sc.append(table);summary.append(sc);detail.append(summary);}
  const timeline=el('div',undefined,'card table-card');const th=el('div',undefined,'subject-heading');th.append(el('h2','날짜별 측정 기록'),button('기본 관찰 요약 CSV',exportSubject),button('주시·이탈 지표 CSV',()=>exportResearchSubject('summary')),button('문항별 시간 CSV',()=>exportResearchSubject('tasks')));timeline.append(th);
  if(!records.length)timeline.append(el('p','아직 기록이 없습니다. 첫 측정을 시작하거나 영상 관찰 기록을 추가하세요.'));
  for(const s of records){const row=el('article',undefined,'session-entry'),h=el('div',undefined,'subject-heading');h.append(el('strong',date(s.startedAt)),el('span',MODES[s.meta.mode]??s.meta.mode,'mode-tag'));row.append(h,el('p',s.meta.session+' · '+fmt(s.referenceOnly?s.referenceGrid.end-s.referenceGrid.start:s.duration)+'초 · '+(s.meta.role==='validation'?'재검증':'개발')));
   const a=summarizeRaterA(s),program=summarizeProgram(s),f=a.fields.find(v=>v.field==='screen'),pf=program.fields.find(v=>v.field==='screen');row.append(el('p','A 화면 판독 '+f.valid+'/'+f.total+'구간 · 프로그램 관측 '+pf.valid+'/'+pf.total+'구간'));
   const snap=s.meta.participantSnapshot,info=el('details');info.append(el('summary','측정 당시 기본정보'));info.append(el('p',snap?(snap.name+' · '+(GENDERS[snap.gender]??'미입력')+' · 나이 '+(snap.age??'미입력')+' · 교정 '+(CORRECTIONS[s.meta.correctionAtSession??snap.correction]??'미입력')+' · 오른눈/왼눈 '+fmt(snap.visionRight,2)+'/'+fmt(snap.visionLeft,2)+' · 시력 기준 '+(({corrected:'교정시력',uncorrected:'나안시력'})[snap.visionBasis]??'미입력')+' · 정보 기준일 '+(snap.ageAsOfDate||'미입력')):'기존 자료 · 측정 당시 기본정보 사본 없음'));row.append(info);
   const buttons=el('div',undefined,'actions');buttons.append(button('기록 보기',()=>openReview(s,false)),button('A 관찰 입력',()=>openReview(s,true)));row.append(buttons);timeline.append(row);}
  detail.append(timeline);const saved=localStorage.getItem('gaze-last-backup-request');$('backupState').textContent=saved?'최근 백업 다운로드 요청: '+date(saved):'아직 이 화면에서 백업하지 않았습니다.';
 }catch(e){notice('대상자 자료 확인: '+e.message,true);}}
 function exportResearchSubject(type){const all=getHistory().filter(s=>s.meta.participant===active&&!s.referenceOnly),rows=[];let headers=null;for(const s of all){const table=researchCSV(s,type);headers??=table[0];rows.push(...table.slice(1));}if(!headers)return notice('이 대상자의 프로그램 측정 기록이 없습니다.');download(csv([headers,...rows]),active+'_research_'+type+'.csv','text/csv;charset=utf-8');}
 function exportSubject(){const sessions=getHistory().filter(s=>s.meta.participant===active),heads=['participant_id','session_id','date','mode','role','source','total_bins','valid_bins','inside_s','outside_s','missing_bins','unclear_bins','failed_bins','name_at_record','gender_at_record','age_at_record','vision_right_at_record','vision_left_at_record','vision_basis_at_record','profile_date_at_record','correction_at_record'];const rows=sessions.flatMap(s=>['a','program'].filter(source=>source==='a'||!s.referenceOnly).map(source=>{const v=sum([s],source);return [active,s.meta.session,s.startedAt,s.meta.mode,s.meta.role,source==='a'?'rater_A':'program',v.total,v.valid,v.inside,v.outside,v.missing,v.unclear,v.failed,s.meta.participantSnapshot?.name,s.meta.participantSnapshot?.gender,s.meta.participantSnapshot?.age,s.meta.participantSnapshot?.visionRight,s.meta.participantSnapshot?.visionLeft,s.meta.participantSnapshot?.visionBasis,s.meta.participantSnapshot?.ageAsOfDate,s.meta.correctionAtSession??s.meta.participantSnapshot?.correction];}));download(csv([heads,...rows]),active+'_records.csv','text/csv;charset=utf-8');}
 $('addSubject').onclick=()=>edit();$('closeProfile').onclick=()=>$('profileDialog').close();$('subjectSearch').oninput=render;
 $('profileForm').onsubmit=e=>{e.preventDefault();try{const fields={id:'profileId',name:'profileName',gender:'profileGender',age:'profileAge',ageAsOfDate:'profileAgeDate',correction:'profileCorrection',visionRight:'profileVisionRight',visionLeft:'profileVisionLeft',visionBasis:'profileVisionBasis',notes:'profileNotes'},p=Object.fromEntries(Object.entries(fields).map(([k,id])=>[k,$(id).value]));const result=repo.saveProfile(p,{replace:!!editing});active=result.id;try{localStorage.setItem('gaze-active-participant',active);}catch{}$('profileDialog').close();render();notice('대상자 정보를 저장했습니다. 측정을 시작하면 이 정보의 사본이 함께 보관됩니다.');}catch(e){$('profileFeedback').textContent=e.message;}};
 $('backupAll').onclick=()=>{if(isBusy())return notice('측정을 종료한 뒤 백업하세요.',true);try{download(JSON.stringify(repo.backup(),null,2),'gaze_all_'+today()+'.json','application/json');localStorage.setItem('gaze-last-backup-request',new Date().toISOString());render();notice('전체 백업 다운로드를 요청했습니다. 이름·시력 정보가 포함된 파일이므로 보관 위치를 확인하세요.');}catch(e){notice('백업 실패: '+e.message,true);}};
 $('restoreAll').onchange=async()=>{const f=$('restoreAll').files[0];if(!f)return;try{if(isBusy())throw Error('측정을 종료한 뒤 백업을 불러오세요.');const result=repo.importBackup(await f.text(),{strategy:$('restoreStrategy').value});onRestored(repo.sessions());render();notice('백업 불러오기 완료 · 대상자 '+result.profiles+'명 / 세션 '+result.sessions+'건을 확인했습니다.');}catch(e){notice('불러오기 실패: '+e.message,true);}finally{$('restoreAll').value='';}};
 return {render,select,selectedProfile,get selectedId(){return active;},edit,act};
}
